// === Tab: mySketch ===
var ratio;
var adjust;
var couleur; 
var x, y;

function setup() {
	createCanvas(windowWidth, windowHeight);
	ratio = 0;
	noStroke();
}

function draw(){

	fill(254,243,198, 200);
	rect(0,0,windowWidth, windowHeight);
	translate(width/2, height/2);

	ratio = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 85, 95);
	adjust = 500/ratio;

	for(var i=-50; i<50; i++){
		for(var j=-50; j<50 ; j++){

			colorize(abs(i*j)%2);
			fill(couleur);
			x = ((i*cos(j)*300)%ratio)*adjust;
			y = ((j*cos(i)*300)%ratio)*adjust;

			if(x!=0 && y!=0 && abs(x)!=abs(y)) ellipse(x,y,4,4);
		}
	}
}

function colorize(a){
	switch(a){
		case 0 : couleur = '#7F70FF';
			break;
		case 1 : couleur = '#7B449D';
			break;
		case 2 : couleur = '#FD4505';
			break;
		case 3 : couleur = '#E9B508';
			break;
	}
}

